                    const replyRegex = /"([^"]+)":\s*\[([^\]]+)\](?:\s*\[([^\]]*)\])?(?:\s*\[([^\]]*)\])?/g;
                    let replyMatch;

                    while ((replyMatch = replyRegex.exec(repliesText)) !== null) {
                        replies.push({
                            username: replyMatch[1],
                            comment: replyMatch[2].trim(),
                            date: replyMatch[3] ? replyMatch[3].trim() : "2024-01-01",
                            likes: replyMatch[4] ? replyMatch[4].trim().replace(/[^\d]/g, '') : "0"
                        });
                    }
                }

                comments.push({
                    username, 
                    comment,
                    level,
                    badge,
                    likes: parseInt(likes) || 0,
                    floor,
                    date,
                    location,
                    replies,
                    totalReplies: replies.length + (replies.length > 3 ? Math.floor(Math.random() * 10) + 1 : 0)
                });
            }

            return comments;
        }

        // 生成评论HTML
        function renderComments(comments) {
            const container = document.getElementById('comments-container');
            container.innerHTML = '';

            comments.forEach(comment => {
                const commentElement = document.createElement('div');
                commentElement.className = 'comment-item';

                // 提取等级数字
                let levelNum = comment.level;
                if (levelNum.startsWith("Lv.")) {
                    levelNum = levelNum;
                } else {
                    levelNum = `Lv.${levelNum}`;
                }

                let commentHTML = `
                    <div class="comment-avatar">
                        <img src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Ccircle cx='50' cy='35' r='25' fill='%234974a4'/%3E%3Cpath d='M50 65 A40 40 0 0 0 10 105 L90 105 A40 40 0 0 0 50 65Z' fill='%234974a4'/%3E%3C/svg%3E" alt="头像">
                    </div>
                    <div class="comment-content">
                        <div class="user-info">
                            <span class="user-name">${comment.username}</span>
                            <span class="user-level">${levelNum}</span>
                            <span class="user-badge">${comment.badge}</span>
                        </div>
                        <div class="comment-text">${comment.comment}</div>
                        <div class="comment-footer">
                            <span class="floor-info">${comment.floor} ${comment.date} ${comment.location}</span>
                            <div class="comment-actions">
                                <div class="like-button" onclick="toggleLike(this, ${comment.likes})">
                                    <i class="fas fa-thumbs-up"></i>
                                    <span class="like-count">${comment.likes}</span>
                                </div>
                                <div class="reply-button" onclick="alert('回复功能暂未开放')">
                                    <i class="fas fa-comment"></i>
                                    <span>回复</span>
                                </div>
                            </div>
                        </div>
                `;

                // 添加回复区域
                if (comment.replies && comment.replies.length > 0) {
                    let repliesHTML = `<div class="replies-container">`;

                    // 限制显示前3条回复
                    const displayedReplies = comment.replies.slice(0, 3);

                    displayedReplies.forEach(reply => {
                        repliesHTML += `
                            <div class="reply-item">
                                <div class="reply-user">
                                    <span class="user-name">${reply.username}</span>
                                </div>
                                <div class="reply-text">${reply.comment}</div>
                                <div class="reply-info">
                                    <span>${reply.date}</span>
                                    <div class="like-button" onclick="toggleLike(this, ${reply.likes})">
                                        <i class="fas fa-thumbs-up"></i>
                                        <span class="like-count">${reply.likes}</span>
                                    </div>
                                </div>
                            </div>
                        `;
                    });

                    // 如果有更多回复，显示查看更多按钮
                    if (comment.totalReplies > 3) {
                        repliesHTML += `
                            <div class="view-more-replies" onclick="alert('该功能暂未开放')">
                                查看全部${comment.totalReplies}条回复
                            </div>
                        `;
                    }

                    repliesHTML += `</div>`;
                    commentHTML += repliesHTML;
                }

                commentHTML += `</div>`;
                commentElement.innerHTML = commentHTML;

                container.appendChild(commentElement);
            });
        }

        // 切换点赞状态
        function toggleLike(element, initialLikes) {
            const likeButton = element;
            const likeCount = likeButton.querySelector('.like-count');

            if (likeButton.classList.contains('active')) {
                likeButton.classList.remove('active');
                likeCount.textContent = parseInt(likeCount.textContent) - 1;
            } else {
                likeButton.classList.add('active');
                likeCount.textContent = parseInt(likeCount.textContent) + 1;
            }
        }

        // 主函数：处理文本内容
        function processTiebaContent() {
            // 获取tieba标签内的内容
            const tiebaContent = `$1`;

            // 检查内容中是否包含吧名
            const baNameMatch = /\[吧名:([^\]]+)\]/.exec(tiebaContent);
            if (baNameMatch) {
                document.getElementById("tieba-name").textContent = baNameMatch[1] + "吧";
            }

            // 检查内容中是否包含帖子标题
            const titleMatch = /\[标题:([^\]]+)\]/.exec(tiebaContent);
            if (titleMatch) {
                document.querySelector(".tieba-header h2").textContent = titleMatch[1];
            }

            // 解析评论数据
            const comments = parseTiebaComments(tiebaContent);

            // 渲染评论
            renderComments(comments);

            // 添加签到按钮事件
            document.querySelector(".tieba-action-btn.sign").addEventListener("click", function() {
                this.textContent = "已签到";
                this.style.backgroundColor = "#999";
                this.disabled = true;
                alert("签到成功！获得15点经验值");
            });

            // 添加搜索按钮事件
            document.querySelector(".tieba-action-btn:not(.sign)").addEventListener("click", function() {
                alert("搜索功能暂未开放");
            });
        }

        // 执行处理
        processTiebaContent();

        // 添加全局点赞切换函数
        window.toggleLike = toggleLike;
    </script>
</body>
</html>

